// Run from strikr-app/ with: node patch-players-and-clubsquiz.js
// Fixes Mode inverse's keyboard-matching bug, adds 101 players, cleans up 5 corrupted entries.
const fs = require('fs');
const path = require('path');

function write(p, content) {
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, content);
  console.log('WROTE:', p);
}

